#include "splinekit.h"
#include <cstdio>
int main(){int count=0,failed=0;auto check=[&](bool ok,const char* why){++count;if(!ok){++failed;std::printf("FAIL %s\n",why);}};using namespace splinekit;
std::vector<Vec> points{{0,0,0},{0,40,20},{30,70,50},{0,100,80}};Plan p;p.enabled=true;AutoHandles(p,points,false);auto curve=Build(points,p,false);check(curve.error.empty()&&curve.points.size()>points.size()&&curve.authored.size()==points.size(),"adaptive 3D cubic path keeps authored anchor correspondence");check(std::fabs(curve.points.back().z-80)<1e-8,"spline bends in all three axes");for(std::size_t i=1;i<curve.points.size();++i)check(Length(Sub(curve.points[i],curve.points[i-1]))<=p.maxStep+.001,"maximum spline step is bounded");
const auto text=Write(p);check(Write(Read(text))==text,"versioned handle data round-trips without precision loss");check(Read("7 future spline").unsupported=="7 future spline","future toolkit records are retained");
ProfileKey a;a.id=p.nextId++;a.at=0;a.profile.width=4;a.profile.height=4;ProfileKey b=a;b.id=p.nextId++;b.at=3;b.profile.width=20;b.profile.height=12;b.profile.bank=4*lanevolume::kPi;b.profile.shape=lanevolume::Shape::Ellipse;p.profiles={a,b};Prepare(p);const auto middle=ProfileAt(p,1.5,0,{});check(std::fabs(middle.width-12)<1e-8&&std::fabs(middle.bank-2*lanevolume::kPi)<1e-8&&middle.polygon.size()==24,"loft interpolates width height outline and unwrapped multi-turn twist");check(lanevolume::Valid(middle),"mixed preset loft has a valid shared polygon topology");
p.profiles.back().profile.bank=12*lanevolume::kPi;Prepare(p);const auto loft=Build(points,p,false);check(loft.error.empty()&&loft.points.size()>curve.points.size(),"rapid profile twist refines the same spline sampling");
lanevolume::Profile concave;concave.shape=lanevolume::Shape::Polygon;concave.polygon={{-.5,0},{.5,0},{.5,1},{0,.5},{-.5,1}};check(lanevolume::Valid(concave)&&lanevolume::Contains(concave,0,concave.height*.25)&&!lanevolume::Contains(concave,0,concave.height*.9),"concave profile containment respects the notch");std::vector<lanevolume::Station> stations{{{0,0,0},concave},{{0,10,0},concave}};const auto mesh=lanevolume::Build(stations,false,lanevolume::Frame::Transport);if(!mesh)std::printf("mesh: %s\n",mesh.error.c_str());check(bool(mesh)&&mesh.faceStation.size()==mesh.triangles.size(),"concave profiles receive triangulated caps and face ownership");
auto crossed=concave;crossed.polygon={{-.5,0},{.5,1},{-.5,1},{.5,0}};check(!lanevolume::Valid(crossed),"self-intersecting profiles do not become executable geometry");
const auto frame=lanevolume::Frames({{0,0,0},{0,0,10},{0,5,20},{5,10,20}},false);check(frame.error.empty()&&frame.right.size()==4&&lanevolume::Length(frame.right[1])>.99,"transport frames stay finite through vertical sections");
Plan huge;huge.enabled=true;std::vector<Vec> far{{0,0,0},{0,100000,0}};AutoHandles(huge,far,false);check(!Build(far,huge,false).error.empty(),"excessive sampling fails explicitly rather than causing unbounded work");
auto cyclic=p;cyclic.profiles.front().at=.3;cyclic.profiles.back().at=2.7;Prepare(cyclic,4,true);const auto nearEnd=ProfileAt(cyclic,3.99999,0,{}),nearStart=ProfileAt(cyclic,.00001,0,{});check(std::fabs(nearEnd.width-nearStart.width)<.001,"closed profile loft interpolates across the seam");const auto fractional=Build(points,cyclic,true);if(!fractional.error.empty())std::printf("fractional: %s\n",fractional.error.c_str());check(fractional.error.empty()&&std::any_of(fractional.source.begin(),fractional.source.end(),[](double u){return std::fabs(u-.3)<1e-9;}),"fractional profile stations are exact adaptive subdivision boundaries");
std::printf("spline toolkit: %d/%d checks passed\n",count-failed,count);return failed?1:0;}
